using namespace std;

using int64 = long long;

// Gregorian calendar utilities for proleptic Gregorian calendar.
// We use Howard Hinnant's days-from-civil / civil-from-days algorithms.
// day 0 = 1970-01-01.

static int64 days_from_civil(int y, unsigned m, unsigned d) {
    y -= m <= 2;
    const int era = (y >= 0 ? y : y - 399) / 400;
    const unsigned yoe = static_cast<unsigned>(y - era * 400);              // [0, 399]
    const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;    // [0, 365]
    const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;             // [0, 146096]
    return era * 146097LL + static_cast<int64>(doe) - 719468LL;
}

static tuple<int,int,int> civil_from_days(int64 z) {
    z += 719468LL;
    const int era = (z >= 0 ? z : z - 146096) / 146097;
    const unsigned doe = static_cast<unsigned>(z - era * 146097LL);          // [0, 146096]
    const unsigned yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;   // [0, 399]
    int y = static_cast<int>(yoe) + era * 400;
    const unsigned doy = doe - (365*yoe + yoe/4 - yoe/100);                  // [0, 365]
    const unsigned mp = (5*doy + 2)/153;                                     // [0, 11]
    const unsigned d = doy - (153*mp + 2)/5 + 1;                             // [1, 31]
    const unsigned m = mp + (mp < 10 ? 3 : -9);                              // [1, 12]
    y += (m <= 2);
    return {y, (int)m, (int)d};
}

