            int64 total = maya_ref + (gdays - greg_ref);

            int64 b  = total / 144000; total %= 144000;
            int64 ka = total / 7200;   total %= 7200;
            int64 t  = total / 360;    total %= 360;
            int64 w  = total / 20;     total %= 20;
            int64 ki = total;

            cout << b << '.' << ka << '.' << t << '.' << w << '.' << ki << "\n";
        } else {
            // Maya -> Gregorian
            int64 b, ka, t, w, ki;
            for (char &c : s) if (c == '.') c = ' ';
            stringstream ss(s);
            ss >> b >> ka >> t >> w >> ki;

