public class Main {
    // Maya Long Count to days conversion constants
    static final long KIN = 1;
    static final long WINAL = 20 * KIN;
    static final long TUN = 18 * WINAL;
    static final long KATUN = 20 * TUN;
    static final long BAKTUN = 20 * KATUN;

    // Maya epoch: 0.0.0.0.0 corresponds to August 11, 3114 BCE (Gregorian)
    // We'll work with a base date of August 11, 3114 BCE (which is Julian day number 584283)
    static final long MAYA_EPOCH_JDN = 584283L; // JDN for August 11, 3114 BCE

    // Reference date: January 1, 1 CE = JDN 1721426
    static final long JDN_1_CE = 1721426L;

    // Days in months for Gregorian calendar (non-leap year)
    static final int[] DAYS_IN_MONTH = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNextLine()) {
            String line = scanner.nextLine().trim();
            if (line.equals("#")) {
                break;
            }

            String[] parts = line.split(" ");
            if (parts.length != 2) continue;

            String input = parts[0];
            String format = parts[1];

            if (format.equals("G")) {
                // Convert Gregorian to Maya
                String[] dateParts = input.split("\\.");
                int year = Integer.parseInt(dateParts[0]);
                int month = Integer.parseInt(dateParts[1]);
                int day = Integer.parseInt(dateParts[2]);

                long jdn = gregorianToJDN(year, month, day);
                long daysSinceMayaEpoch = jdn - MAYA_EPOCH_JDN;

                long baktun = daysSinceMayaEpoch / BAKTUN;
                long remainder = daysSinceMayaEpoch % BAKTUN;
                long katun = remainder / KATUN;
                remainder %= KATUN;
                long tun = remainder / TUN;
                remainder %= TUN;
                long winal = remainder / WINAL;
                long kin = remainder % WINAL;

                System.out.println(baktun + "." + katun + "." + tun + "." + winal + "." + kin);

            } else if (format.equals("M")) {
                // Convert Maya to Gregorian
                String[] mayaParts = input.split("\\.");
                long baktun = Long.parseLong(mayaParts[0]);
                long katun = Long.parseLong(mayaParts[1]);
                long tun = Long.parseLong(mayaParts[2]);
                long winal = Long.parseLong(mayaParts[3]);
                long kin = Long.parseLong(mayaParts[4]);

                long totalDays = baktun * BAKTUN + katun * KATUN + tun * TUN + winal * WINAL + kin;
                long jdn = MAYA_EPOCH_JDN + totalDays;

                int[] gregorianDate = jdnToGregorian(jdn);
                System.out.println(gregorianDate[0] + "." + gregorianDate[1] + "." + gregorianDate[2]);
            }
        }

        scanner.close();
    }

    // Convert Gregorian date to Julian Day Number
    static long gregorianToJDN(int year, int month, int day) {
        // Handle BCE years: year 1 BCE = 0, year 2 BCE = -1, etc.
        if (year <= 0) {
            year++; // Adjust: year 0 is 1 BCE, year -1 is 2 BCE, etc.
        }

        long a = (14 - month) / 12;
        long y = year + 4800 - a;
        long m = month + 12 * a - 3;

        long jdn = day + (153 * m + 2) / 5 + 365 * y + y / 4 - y / 100 + y / 400 - 32045;

        return jdn;
    }

    // Convert Julian Day Number to Gregorian date
    static int[] jdnToGregorian(long jdn) {
        long a = jdn + 32044;
        long b = (4 * a + 3) / 146097;
        long c = a - (146097 * b) / 4;
        long d = (4 * c + 3) / 1461;
        long e = c - (1461 * d) / 4;
        long m = (5 * e + 2) / 153;

        int day = (int)(e - (153 * m + 2) / 5 + 1);
        int month = (int)(m + 3 - 12 * (m / 10));
        int year = (int)(100 * b + d - 4800 + m / 10);

        // Handle BCE years: year 0 = 1 BCE, year -1 = 2 BCE, etc.
        if (year <= 0) {
            year--; // Convert back: year 1 BCE = 0, year 2 BCE = -1, etc.
        }

        return new int[]{year, month, day};
    }
}

